  void Safe(Action action){try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"OpenEletric",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
  void Change(){dirty=true;revision++;RefreshAll();}
  void SelectObject(object item){if(item is Board){board=(Board)item;circuit=null;properties.SelectedObject=board;RefreshContent();}else if(item is Circuit){circuit=(Circuit)item;board=project.Boards.First(b=>b.Circuits.Contains(circuit));properties.SelectedObject=circuit;RefreshContent();SelectGrid(circuit);}else{properties.SelectedObject=project;tabs.SelectedIndex=0;}}
  void RefreshAll(){sync=true;tree.BeginUpdate();tree.Nodes.Clear();var root=tree.Nodes.Add(project.Name);root.Tag=project;foreach(var b in project.Boards){var node=root.Nodes.Add(b.Name);node.Tag=b;foreach(var c in b.Circuits){var child=node.Nodes.Add(c.Id+"  "+c.Name);child.Tag=c;}}root.Expand();foreach(TreeNode n in root.Nodes)if(n.Tag==board)n.Expand();tree.EndUpdate();sync=false;RefreshContent();}
  void RefreshContent(){
   if(board==null||!project.Boards.Contains(board))board=project.Boards.FirstOrDefault();if(circuit!=null&&(board==null||!board.Circuits.Contains(circuit)))circuit=null;
   heading.Text=project.Name;description.Text=(string.IsNullOrWhiteSpace(project.Client)?"Cliente não informado":project.Client)+"   /   "+(string.IsNullOrWhiteSpace(project.Site)?"Local não informado":project.Site);
   var all=project.Boards.SelectMany(b=>b.Circuits).ToList();currentStudy=Engineering.Analyze(project);summary.Text=project.Boards.Count+" quadros     •     "+all.Count+" circuitos     •     "+all.Where(c=>string.IsNullOrEmpty(c.ChildBoardId)).Sum(c=>c.PowerKw).ToString("N2")+" kW instalados     •     "+currentStudy.TotalKw.ToString("N2")+" kW de demanda";
   overview.Text="PROJETO\r\n"+project.Name+"\r\n\r\nCliente: "+project.Client+"\r\nLocal: "+project.Site+"\r\nResponsável: "+project.Designer+"\r\nDescrição (linhas 1–3):\r\n"+String.Join("\r\n",project.DescriptionRows)+"\r\nSistema de aterramento: "+project.Earthing+"\r\nFrequência: "+project.Frequency+" Hz\r\n\r\nQUADROS\r\n"+string.Join("\r\n",project.Boards.Select(b=>b.Name+"  ·  "+b.Voltage+" V  ·  "+b.Circuits.Count+" circuitos"))+"\r\n\r\nFLUXO DE TRABALHO\r\n1. Selecione projeto, quadro ou circuito na lateral.\r\n2. Edite os campos em Propriedades, à direita.\r\n3. Confira a tabela e o diagrama unifilar.\r\n4. Salve o projeto e exporte seu relatório.\r\n\r\nCÁLCULOS DESTA VERSÃO\r\nCorrente de carga monofásica e trifásica equilibrada.\r\nPotências são elétricas de entrada; demanda é informada pelo usuário. Estudos de cabos e proteção na aba Estudos. Dados não informados geram pendências.\r\n\r\nNotas: "+project.Notes;
   grid.Columns["Current"].HeaderText=currentStudy.NetworkFlow==null?"Carga · A":"Nominal · A";grid.Columns["Voltage"].HeaderText=currentStudy.NetworkFlow==null?"V":"Nominal · V";sync=true;grid.Rows.Clear();if(board!=null)foreach(var c in board.Circuits){int i=grid.Rows.Add(c.Id,c.Name,c.PowerKw.ToString("N2"),c.Voltage.ToString("N0"),currentStudy.For(c).CurrentA.ToString("N2"),c.CableMm2>0?c.CableMm2.ToString("N2"):"—",c.BreakerA>0?c.BreakerA.ToString("N0"):"—");grid.Rows[i].Tag=c;}grid.ClearSelection();sync=false;if(circuit!=null)SelectGrid(circuit);
   RefreshStudies();diagram.Study=currentStudy;diagram.Project=project;diagram.Board=board;diagram.Selected=circuit;diagram.UpdateSize();diagram.Invalidate();properties.Refresh();Text=(dirty?"● ":"")+project.Name+" — OpenEletric";status.Text=(currentFile==null?"Projeto ainda não salvo":Path.GetFileName(currentFile))+"   ·   "+(board==null?"Selecione um quadro":board.Name)+"   ·   Confira resultados e pendências na aba Estudos";
