  void SelectGrid(Circuit c){sync=true;foreach(DataGridViewRow r in grid.Rows)r.Selected=r.Tag==c;sync=false;diagram.Selected=c;diagram.Invalidate();}
  void PropertyChanged(object sender,PropertyValueChangedEventArgs e){try{project.Validate();Change();}catch(Exception ex){var descriptor=e.ChangedItem.PropertyDescriptor;object owner=properties.SelectedObject;for(var parent=e.ChangedItem.Parent;parent!=null;parent=parent.Parent)if(parent.Value!=null&&descriptor.ComponentType.IsInstanceOfType(parent.Value)){owner=parent.Value;break;}descriptor.SetValue(owner,e.OldValue);properties.Refresh();MessageBox.Show(this,ex.Message,"Valor inválido",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
  bool ConfirmDiscard(){if(!dirty)return true;var result=MessageBox.Show(this,"Salvar as alterações antes de continuar?","Projeto modificado",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(result==DialogResult.Cancel)return false;if(result==DialogResult.No)return true;try{return Save(false);}catch(Exception ex){MessageBox.Show(ex.Message);return false;}}
  void NewProject(){if(!ConfirmDiscard())return;using(var wizard=new ProjectWizard()){if(wizard.ShowDialog(this)!=DialogResult.OK)return;project=wizard.Result;board=project.Boards.FirstOrDefault();circuit=null;currentFile=null;dirty=true;revision++;RefreshAll();properties.SelectedObject=project;tabs.SelectedIndex=0;}}
  void OpenProject(){if(!ConfirmDiscard())return;using(var d=new OpenFileDialog{Filter="Projeto OpenEletric (*.circuito)|*.circuito|JSON (*.json)|*.json",Title="Abrir projeto"}){if(d.ShowDialog()!=DialogResult.OK)return;OpenProjectPath(d.FileName);}}
  public void OpenProjectPath(string path){string full=Path.GetFullPath(path);Project loaded=Project.Load(full);project=loaded;currentFile=full;board=project.Boards.FirstOrDefault();circuit=null;dirty=false;RefreshAll();properties.SelectedObject=project;}
  string Folder(){string configured=Environment.GetEnvironmentVariable("CIRCUITO_PROJECTS_DIR");string p=String.IsNullOrWhiteSpace(configured)?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"OpenEletric"):configured;try{Directory.CreateDirectory(p);return p;}catch{return Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);}}
  bool Save(bool saveAs){string target=currentFile;if(saveAs||string.IsNullOrEmpty(target)){using(var d=new SaveFileDialog{Filter="Projeto OpenEletric (*.circuito)|*.circuito",DefaultExt="circuito",FileName=SafeName(project.Name)+".circuito",InitialDirectory=Folder()}){if(d.ShowDialog()!=DialogResult.OK)return false;target=d.FileName;}}project.Validate();project.Save(target);currentFile=target;dirty=false;RefreshContent();status.Text="Projeto salvo: "+target;return true;}
  static string SafeName(string name){foreach(char c in Path.GetInvalidFileNameChars())name=name.Replace(c,'_');return string.IsNullOrWhiteSpace(name)?"Projeto":name;}
  void AddBoard(){board=ProjectEditing.AddBoard(project);circuit=null;Change();properties.SelectedObject=board;tabs.SelectedIndex=1;}
  void DeleteBoard(){if(board==null)return;int incoming=project.Boards.SelectMany(b=>b.Circuits).Count(c=>c.ChildBoardId==board.Id);string note="Excluir "+board.Name+" e seus circuitos?\r\nAlimentadores que chegam a este quadro também serão removidos: "+incoming+".\r\nQuadros a jusante permanecerão como raízes independentes.";if(MessageBox.Show(note,"Excluir quadro",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;ProjectEditing.RemoveBoard(project,board);board=project.Boards.FirstOrDefault();circuit=null;Change();properties.SelectedObject=project;}
  void AddCircuit(){if(board==null)AddBoard();circuit=ProjectEditing.AddCircuit(project,board);Change();properties.SelectedObject=circuit;tabs.SelectedIndex=1;}
  void DuplicateCircuit(){if(circuit==null||board==null)return;circuit=ProjectEditing.DuplicateCircuit(project,board,circuit);Change();properties.SelectedObject=circuit;tabs.SelectedIndex=1;}
  void DeleteCircuit(){if(circuit==null||board==null)return;string note=circuit.ChildBoardId==""?"":"\r\nO quadro a jusante continuará no projeto como uma raiz independente.";if(MessageBox.Show("Excluir o circuito "+circuit.Id+"?"+note,"Excluir circuito",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;ProjectEditing.RemoveCircuit(project,board,circuit);circuit=null;Change();properties.SelectedObject=board;}
  void Export(string kind){project.Validate();if(kind=="svg"&&board==null)throw new InvalidOperationException("Crie ou selecione um quadro para exportar o unifilar.");using(var d=new SaveFileDialog{Filter=kind.ToUpperInvariant()+" (*."+kind+")|*."+kind,FileName=SafeName(project.Name)+(kind=="svg"?"-"+SafeName(board.Name):"")+"."+kind,InitialDirectory=Folder()}){if(d.ShowDialog()!=DialogResult.OK)return;if(kind=="csv")Exports.Csv(project,d.FileName);else if(kind=="svg")Exports.Svg(project,board,d.FileName);else EngineeringReport.Html(project,d.FileName);status.Text="Exportado: "+d.FileName;}}
 }
