  static void DrawLine(Graphics g,string text,Font f,Brush b,Rectangle r){using(var format=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap})g.DrawString(text,f,b,r,format);}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;foreach(var pair in hit)if(pair.Key.Contains(e.Location)){dragged=pair.Value;dragOrigin=e.Location;originalX=pair.Key.X+30;originalY=pair.Key.Y-132;moved=false;Capture=true;break;}}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragged==null||e.Button!=MouseButtons.Left)return;int dx=e.X-dragOrigin.X,dy=e.Y-dragOrigin.Y;if(!moved&&Math.Abs(dx)+Math.Abs(dy)<5)return;moved=true;dragged.DiagramX=Math.Max(45,Math.Min(4000,originalX+dx));dragged.DiagramY=Math.Max(115,Math.Min(4000,originalY+dy));Invalidate();}
  protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(dragged==null)return;var c=dragged;dragged=null;Capture=false;if(moved){UpdateSize();if(CircuitMoved!=null)CircuitMoved(c);}moved=false;}
  protected override void OnMouseClick(MouseEventArgs e){base.OnMouseClick(e);foreach(var pair in hit)if(pair.Key.Contains(e.Location)){Selected=pair.Value;Invalidate();if(CircuitClicked!=null)CircuitClicked(Selected);break;}}
 }
}
